// Build yesterday's summary from both sheet reads.
// Ads come from the 'Read Ad Numbers' node, deals from the current input.
const yesterday = $now.minus({ days: 1 }).toFormat('yyyy-MM-dd');

const adRows = $('Read Ad Numbers').all()
  .map(i => i.json)
  .filter(r => r && String(r.date) === yesterday);

const dealRows = $input.all()
  .map(i => i.json)
  .filter(r => r && String(r.date) === yesterday && r.deal_name);

// Group ad rows by source (meta, google, ...)
const bySource = {};
for (const r of adRows) {
  const src = String(r.source || 'unknown').toLowerCase();
  if (!bySource[src]) bySource[src] = { spend: 0, leads: 0 };
  bySource[src].spend += Number(r.spend) || 0;
  bySource[src].leads += Number(r.leads) || 0;
}

const money = n => '$' + n.toFixed(2);
const cpl = (s, l) => (l > 0 ? money(s / l) : 'n/a');

let totalSpend = 0, totalLeads = 0;
const sourceLines = [];
for (const [src, v] of Object.entries(bySource)) {
  totalSpend += v.spend;
  totalLeads += v.leads;
  sourceLines.push(`  • ${src}: ${money(v.spend)} spend, ${v.leads} leads, CPL ${cpl(v.spend, v.leads)}`);
}
if (sourceLines.length === 0) sourceLines.push('  • No ad data found for yesterday. Check the sources!');

const dealLines = dealRows.map(d => `  • ${d.deal_name}: ${d.from_stage} -> ${d.to_stage}`);
if (dealLines.length === 0) dealLines.push('  • No deals moved yesterday.');

const text = [
  `☀️ *Morning Numbers, ${yesterday}*`,
  '',
  '*Ad performance:*',
  ...sourceLines,
  '',
  `*Totals:* ${money(totalSpend)} spend | ${totalLeads} leads | CPL ${cpl(totalSpend, totalLeads)}`,
  '',
  `*Deals moved (${dealRows.length}):*`,
  ...dealLines,
].join('\n');

return [{ json: { text, total_spend: totalSpend, total_leads: totalLeads } }];

